import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public class SWRG extends ItemPE implements IPedestalItem, IProjectileShooter, ICapabilityAware {

	public SWRG(Properties props) {
		super(props.component(PEDataComponentTypes.SWRG_MODE, SWRGMode.OFF)
				.component(PEDataComponentTypes.STORED_EMC, 0L)
				.component(PEDataComponentTypes.UNPROCESSED_EMC, 0.0)
		);
	}

	private void tick(ItemStack stack, Player player) {
		SWRGMode mode = getMode(stack);
		if (mode.hasShield()) {
			// Repel on both sides - smooth animation
			WorldHelper.repelEntitiesSWRG(player.level(), player.getBoundingBox().inflate(5), player);
		}
		if (player.level().isClientSide) {
			return;
		}
		if (!hasEmc(player, stack, 64, true)) {
			//If it is already off changeMode will just NO-OP
			changeMode(player, stack, mode, SWRGMode.OFF);
			return;
		}

		if (player.getAbilities().flying) {
			if (!mode.hasFlight()) {
				mode = changeMode(player, stack, mode, mode.toggleFlight());
			}
		} else if (mode.hasFlight()) {
			mode = changeMode(player, stack, mode, mode.toggleFlight());
		}

		float toRemove = mode.hasShield() ? 0.32F : 0;
		if (mode.hasFlight() && player.getAbilities().flying) {
			toRemove += 0.32F;
		}

		removeEmc(stack, toRemove);
	}

	@Override
	public void inventoryTick(@NotNull ItemStack stack, @NotNull Level level, @NotNull Entity entity, int slot, boolean isHeld) {
		super.inventoryTick(stack, level, entity, slot, isHeld);
		if (hotBarOrOffHand(slot) && entity instanceof Player player) {
			tick(stack, player);
		}
	}

	private SWRGMode getMode(ItemStack stack) {
		return stack.getOrDefault(PEDataComponentTypes.SWRG_MODE, SWRGMode.OFF);
	}

	@NotNull
	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, @NotNull InteractionHand hand) {
		ItemStack stack = player.getItemInHand(hand);
		if (!level.isClientSide) {
			SWRGMode oldMode = getMode(stack);
			changeMode(player, stack, oldMode, oldMode.next());
		}
		return InteractionResultHolder.success(stack);
	}

	private SWRGMode changeMode(Player player, ItemStack stack, SWRGMode oldMode, SWRGMode mode) {
		if (mode == oldMode) {
			return mode;
		}
		stack.set(PEDataComponentTypes.SWRG_MODE, mode);
		if (player == null) {
			//Don't do sounds if the player is null
			return mode;
		}
		if (mode == SWRGMode.OFF || oldMode == SWRGMode.SHIELDED_FLIGHT) {
			//At least one mode deactivated
			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), PESoundEvents.UNCHARGE.get(), SoundSource.PLAYERS, 0.8F, 1.0F);
		} else if (oldMode == SWRGMode.OFF || mode == SWRGMode.SHIELDED_FLIGHT) {
			//At least one mode activated
			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), PESoundEvents.HEAL.get(), SoundSource.PLAYERS, 0.8F, 1.0F);
		}
		//Doesn't handle going from mode 1 to 2 or 2 to 1
		return mode;
	}

	@Override
	public boolean isBarVisible(@NotNull ItemStack stack) {
		return false;
	}

	@Override
	public <PEDESTAL extends BlockEntity & IDMPedestal> boolean updateInPedestal(@NotNull ItemStack stack, @NotNull Level level, @NotNull BlockPos pos,
			@NotNull PEDESTAL pedestal) {
		if (!level.isClientSide && ProjectEConfig.server.cooldown.pedestal.swrg.get() != -1) {
			if (pedestal.getActivityCooldown() <= 0) {
				for (Mob living : level.getEntitiesOfClass(Mob.class, pedestal.getEffectBounds(),
						ent -> !ent.isSpectator() && (!(ent instanceof TamableAnimal tamableAnimal) || !tamableAnimal.isTame()))) {
					LightningBolt lightning = EntityType.LIGHTNING_BOLT.create(level);
					if (lightning != null) {
						lightning.moveTo(living.position());
						level.addFreshEntity(lightning);
					}
				}
				pedestal.setActivityCooldown(level, pos, ProjectEConfig.server.cooldown.pedestal.swrg.get());
			} else {
				pedestal.decrementActivityCooldown(level, pos);
			}
		}
		return false;
	}

	@NotNull
	@Override
	public List<Component> getPedestalDescription(float tickRate) {
		List<Component> list = new ArrayList<>();
		if (ProjectEConfig.server.cooldown.pedestal.swrg.get() != -1) {
			list.add(PELang.PEDESTAL_SWRG_1.translateColored(ChatFormatting.BLUE));
			list.add(PELang.PEDESTAL_SWRG_2.translateColored(ChatFormatting.BLUE, MathUtils.tickToSecFormatted(ProjectEConfig.server.cooldown.pedestal.swrg.get(), tickRate)));
		}
		return list;
	}

	@Override
	public boolean shootProjectile(@NotNull Player player, @NotNull ItemStack stack, @Nullable InteractionHand hand) {
		EntitySWRGProjectile projectile = new EntitySWRGProjectile(player, false, player.level());
		projectile.shootFromRotation(player, player.getXRot(), player.getYRot(), 0, 1.5F, 1);
		player.level().addFreshEntity(projectile);
		return true;
	}

	@Override
	public void attachCapabilities(RegisterCapabilitiesEvent event) {
		IntegrationHelper.registerCuriosCapability(event, this);
	}

	public enum SWRGMode implements StringRepresentable {//Change the mode of SWRG. Modes:<p> 0 = Ring Off<p> 1 = Flight<p> 2 = Shield<p> 3 = Flight + Shield<p>
		OFF,
		FLIGHT,
		SHIELD,
		SHIELDED_FLIGHT;

		public static final Codec<SWRGMode> CODEC = StringRepresentable.fromEnum(SWRGMode::values);
		public static final IntFunction<SWRGMode> BY_ID = ByIdMap.continuous(SWRGMode::ordinal, values(), ByIdMap.OutOfBoundsStrategy.WRAP);
		public static final StreamCodec<ByteBuf, SWRGMode> STREAM_CODEC = ByteBufCodecs.idMapper(BY_ID, SWRGMode::ordinal);

		private final String serializedName;

		SWRGMode() {
			this.serializedName = name().toLowerCase(Locale.ROOT);
		}

		@NotNull
		@Override
		public String getSerializedName() {
			return serializedName;
		}

		public boolean hasFlight() {
			return this == FLIGHT || this == SHIELDED_FLIGHT;
		}

		public boolean hasShield() {
			return this == SHIELD || this == SHIELDED_FLIGHT;
		}

		public SWRGMode toggleFlight() {
			return switch (this) {
				case OFF -> FLIGHT;
				case SHIELD -> SHIELDED_FLIGHT;
				case FLIGHT -> OFF;
				case SHIELDED_FLIGHT -> SHIELD;
			};
		}

		public SWRGMode next() {
			return switch (this) {
				case OFF -> SHIELD;
				case SHIELD -> OFF;
				case FLIGHT -> SHIELDED_FLIGHT;
				case SHIELDED_FLIGHT -> FLIGHT;
			};
		}
	}
}

package moze_intel.projecte.gameObjs.items;

import java.util.Objects;
import moze_intel.projecte.api.capabilities.item.IModeChanger;
import moze_intel.projecte.gameObjs.registries.PEDataComponentTypes;
import moze_intel.projecte.utils.EMCHelper;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import org.jetbrains.annotations.Range;

public class ItemPE extends Item {

	public ItemPE(Properties props) {
		super(props);
	}

	@Override
	public boolean shouldCauseReequipAnimation(ItemStack oldStack, ItemStack newStack, boolean slotChanged) {
		if (oldStack.getItem() != newStack.getItem()) {
			return true;
		} else if (oldStack.getOrDefault(PEDataComponentTypes.ACTIVE, false) != newStack.getOrDefault(PEDataComponentTypes.ACTIVE, false)) {
			return true;
		}
		return this instanceof IModeChanger<?> modeChanger && !modeMatches(modeChanger, oldStack, newStack);
	}

	private static <MODE> boolean modeMatches(IModeChanger<MODE> modeChanger, ItemStack oldStack, ItemStack newStack) {
		return Objects.equals(modeChanger.getMode(oldStack), modeChanger.getMode(newStack));
	}

	@Range(from = 0, to = Long.MAX_VALUE)
	private static long getEmc(ItemStack stack) {
		return stack.getOrDefault(PEDataComponentTypes.STORED_EMC, 0L);
	}

	public static void removeEmc(ItemStack stack, float amount) {
		removeEmc(stack, EMCHelper.removeFractionalEMC(stack, amount));
	}

	public static void removeEmc(ItemStack stack, @Range(from = 0, to = Long.MAX_VALUE) long amount) {
		if (amount > 0) {
			stack.update(PEDataComponentTypes.STORED_EMC, 0L, amount, (emc, change) -> Math.max(emc - change, 0));
		}
	}

	public static boolean hasEmc(Player player, ItemStack stack, @Range(from = 0, to = Long.MAX_VALUE) long amount, boolean subUnitRemoval) {
		if (subUnitRemoval && getEmc(stack) > 0) {
			return true;
		}
		return consumeFuel(player, stack, amount, false);
	}

	/**
	 * If this method returns true (and shouldRemove is false), it can be assumed the stack has at least the given amount of emc stored.
	 */
	public static boolean consumeFuel(Player player, ItemStack stack, @Range(from = 0, to = Long.MAX_VALUE) long amount, boolean shouldRemove) {
		if (amount <= 0) {
			return true;
		}
		long current = getEmc(stack);
		boolean updateEmc = shouldRemove;
		if (current < amount) {
			long consume = EMCHelper.consumePlayerFuel(player, amount - current);
			if (consume == -1) {
				return false;
			}
			long spaceFor = Long.MAX_VALUE - current;
			if (consume > spaceFor) {
				if (shouldRemove) {
					//Remove the amount from consume, and mark we don't need to remove it
					consume -= amount;
					shouldRemove = false;
					//Check if we can now account for all that we consumed in the space we have
					if (consume > spaceFor) {//If it is still too large clamp it
						current = Long.MAX_VALUE;
					} else {//Otherwise, add it
						current += consume;
					}
				} else {//If we are not removing, just clamp the amount we have
					current = Long.MAX_VALUE;
				}
			} else {
				current += consume;
			}
			updateEmc = true;
		}
		if (shouldRemove) {
			//Note: Even if current < amount when we started, we will exit early if we were not able to consume enough emc to get us to have consume >= amount
			current -= amount;
		}
		if (updateEmc) {
			stack.set(PEDataComponentTypes.STORED_EMC, current);
		}
		return true;
	}

	public static boolean hotBarOrOffHand(int slot) {
		return slot < Inventory.getSelectionSize() || slot == Inventory.SLOT_OFFHAND;
	}
}

public static boolean validRepelEntity(Entity entity, TagKey<EntityType<?>> blacklistTag) {
	if (!entity.isSpectator() && !entity.getType().is(blacklistTag)) {
		if (entity instanceof Projectile) {
			//Accept any projectile's that are not in the ground, but fail for ones that are in the ground
			return !entity.onGround();
		}
		return entity instanceof Mob;
	}
	return false;
}

/**
 * Repels projectiles and mobs in the given AABB away from a given player, if the player is not the thrower of the projectile
 */
public static void repelEntitiesSWRG(Level level, AABB effectBounds, Player player) {
	Vec3 playerVec = player.position();
	for (Entity ent : level.getEntitiesOfClass(Entity.class, effectBounds, SWRG_REPEL_PREDICATE)) {
		if (ent instanceof Projectile projectile) {
			Entity owner = projectile.getOwner();
			//Note: Eventually we would like to remove the check for if the world is remote and the thrower is null, but
			// it is needed to make sure it renders properly for when a player throws an ender pearl, or other throwable
			// as the client doesn't know the owner of things like ender pearls and thus renders it improperly
			if (level.isClientSide() && owner == null || owner != null && player.getUUID().equals(owner.getUUID())) {
				continue;
			}
		}
		repelEntity(playerVec, ent);
	}
}

public static void repelEntity(Vec3 vec, Entity entity) {
	double distance = vec.distanceTo(entity.position()) + 0.1;
	entity.push(entity.position()
			.subtract(vec)
			.scale(1 / (1.5 * distance)));
}

public static long consumePlayerFuel(Player player, @Range(from = 0, to = Long.MAX_VALUE) long minFuel) {
	if (player.isCreative() || minFuel == 0) {
		return minFuel;
	}
	IItemHandler curios = player.getCapability(IntegrationHelper.CURIO_ITEM_HANDLER);
	if (curios != null) {
		for (int i = 0, slots = curios.getSlots(); i < slots; i++) {
			long actualExtracted = tryExtract(curios.getStackInSlot(i), minFuel);
			if (actualExtracted > 0) {
				player.containerMenu.broadcastChanges();
				return actualExtracted;
			}
		}
	}

	//Note: The implementation of this will iterate in the order: Main inventory, Armor, Offhand
	IItemHandler inv = player.getCapability(ItemHandler.ENTITY);
	if (inv != null) {
		//Ensure that we have an item handler capability, because if for example the player is dead we will not
		Int2IntMap map = new Int2IntOpenHashMap();
		boolean metRequirement = false;
		long emcConsumed = 0;
		for (int i = 0, slots = inv.getSlots(); i < slots; i++) {
			ItemStack stack = inv.getStackInSlot(i);
			if (stack.isEmpty()) {
				continue;
			}
			long actualExtracted = tryExtract(stack, minFuel);
			if (actualExtracted > 0) { //Prioritize extracting from emc storage items
				player.containerMenu.broadcastChanges();
				return actualExtracted;
			} else if (!metRequirement && FuelMapper.isStackFuel(stack)) {
				//TODO: Should we be validating we simulate that we will be able to extract the stack and how much of it?
				long emc = IEMCProxy.INSTANCE.getValue(stack);
				int toRemove = Mth.ceil((double) (minFuel - emcConsumed) / emc);
				int actualRemoved = Math.min(stack.getCount(), toRemove);
				if (actualRemoved > 0) {
					map.put(i, actualRemoved);
					emcConsumed += emc * actualRemoved;
					metRequirement = emcConsumed >= minFuel;
				}
			}
		}
		if (metRequirement) {
			for (Iterator<Int2IntMap.Entry> iterator = Int2IntMaps.fastIterator(map); iterator.hasNext(); ) {
				Int2IntMap.Entry entry = iterator.next();
				//TODO: Should we be validating we were able to actually extract the items?
				inv.extractItem(entry.getIntKey(), entry.getIntValue(), false);
			}
			player.containerMenu.broadcastChanges();
			return emcConsumed;
		}
	}
	return -1;
}

private static long tryExtract(@NotNull ItemStack stack, long minFuel) {
	IItemEmcHolder emcHolder = stack.getCapability(PECapabilities.EMC_HOLDER_ITEM_CAPABILITY);
	if (emcHolder != null) {
		long simulatedExtraction = emcHolder.extractEmc(stack, minFuel, EmcAction.SIMULATE);
		if (simulatedExtraction >= minFuel) {
			return emcHolder.extractEmc(stack, simulatedExtraction, EmcAction.EXECUTE);
		}
	}
	return 0;
}

public static long removeFractionalEMC(ItemStack stack, double amount) {
	double unprocessedEMC = stack.getOrDefault(PEDataComponentTypes.UNPROCESSED_EMC, 0.0);
	unprocessedEMC += amount;
	long toRemove = (long) unprocessedEMC;
	unprocessedEMC -= toRemove;
	stack.set(PEDataComponentTypes.UNPROCESSED_EMC, unprocessedEMC);
	return toRemove;
}

package moze_intel.projecte.handlers;

import com.google.common.base.Predicates;
import java.util.function.Predicate;
import moze_intel.projecte.PECore;
import moze_intel.projecte.gameObjs.items.ItemPE;
import moze_intel.projecte.gameObjs.registries.PEItems;
import moze_intel.projecte.utils.PlayerHelper;
import net.minecraft.core.Holder;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.material.FluidState;
import net.neoforged.neoforge.common.NeoForgeMod;

public class InternalAbilities {

	private static final AttributeModifier FLIGHT = new AttributeModifier(PECore.rl("flight"), 1, Operation.ADD_VALUE);
	private static final AttributeModifier WATER_SPEED_BOOST = new AttributeModifier(PECore.rl("water_speed_boost"), 0.15, Operation.ADD_VALUE);
	private static final AttributeModifier LAVA_SPEED_BOOST = new AttributeModifier(PECore.rl("lava_speed_boost"), 0.15, Operation.ADD_VALUE);

	public static void tick(Player player) {
		Predicate<Player> applyWaterSpeed = Predicates.alwaysFalse();
		Predicate<Player> applyLavaSpeed = Predicates.alwaysFalse();
		WalkOnType waterWalkOnType = canWalkOnWater(player);
		WalkOnType lavaWalkOnType = canWalkOnLava(player);
		if (waterWalkOnType.canWalk() || lavaWalkOnType.canWalk()) {
			FluidState below = player.level().getFluidState(player.getOnPos());
			boolean water = waterWalkOnType.canWalk() && below.is(FluidTags.WATER);
			//Note: Technically we could probably only have lava be true if water is false, but given the
			// fact vanilla uses tags for logic and technically (although it probably would cause lots of
			// weirdness, the block we are standing on could be both water and lava, which would mean that
			// we would want to apply both speed boosts).
			boolean lava = lavaWalkOnType.canWalk() && below.is(FluidTags.LAVA);
			if ((water || lava) && player.getInBlockState().isAir()) {
				if (!player.isShiftKeyDown()) {
					player.setDeltaMovement(player.getDeltaMovement().multiply(1, 0, 1));
					player.resetFallDistance();
					player.setOnGround(true);
				}
				applyWaterSpeed = waterWalkOnType.applySpeed(water);
				applyLavaSpeed = lavaWalkOnType.applySpeed(lava);
			} else if (!player.level().isClientSide) {
				if (waterWalkOnType.canWalk() && player.isInWater()) {
					//Things that apply water walking also refresh air supply when in water
					player.setAirSupply(player.getMaxAirSupply());
				}
			}
		}
		if (!player.level().isClientSide) {
			updateAttribute(player, Attributes.MOVEMENT_SPEED, WATER_SPEED_BOOST, applyWaterSpeed);
			updateAttribute(player, Attributes.MOVEMENT_SPEED, LAVA_SPEED_BOOST, applyLavaSpeed);
			updateAttribute(player, NeoForgeMod.CREATIVE_FLIGHT, FLIGHT, InternalAbilities::shouldPlayerFly);
		}
	}

	//Note: The attributes that currently use this cannot be converted to just being attributes on the items, as they can be disabled based on the player state
	private static void updateAttribute(Player player, Holder<Attribute> attribute, AttributeModifier modifier, Predicate<Player> applyAttribute) {
		AttributeInstance attributeInstance = player.getAttribute(attribute);
		if (attributeInstance != null) {
			boolean hasModifier = attributeInstance.hasModifier(modifier.id());
			if (applyAttribute.test(player)) {
				if (!hasModifier) {
					//Should have it, but doesn't have the modifier yet, add it
					attributeInstance.addTransientModifier(modifier);
				}
			} else if (hasModifier) {
				//Shouldn't have the modifier, remove it
				attributeInstance.removeModifier(modifier.id());
			}
		}
	}

	private static boolean shouldPlayerFly(Player player) {
		return PlayerHelper.checkHotbarCurios(player, (p, stack) -> stack.is(PEItems.SWIFTWOLF_RENDING_GALE) && ItemPE.hasEmc(p, stack, 64, true))
			   //Note: Curios, and the offhand are handled by the attribute on the arcana ring. We want it to provide flight in other slots on the hotbar as well
			   // so we have to do it here. We do this rather than only doing a hotbar curios check with no attribute, so that the tooltip shows it provides flight
			   || PlayerHelper.checkHotbar(player, (p, stack) -> stack.is(PEItems.ARCANA_RING));
	}

	private static WalkOnType canWalkOnWater(Player player) {
		if (PlayerHelper.checkHotbarCurios(player, (p, stack) -> stack.is(PEItems.EVERTIDE_AMULET))) {
			return WalkOnType.ABLE_WITH_SPEED;
		}
		ItemStack helmet = player.getItemBySlot(EquipmentSlot.HEAD);
		return !helmet.isEmpty() && helmet.is(PEItems.GEM_HELMET) ? WalkOnType.ABLE : WalkOnType.UNABLE;
	}

	private static WalkOnType canWalkOnLava(Player player) {
		if (PlayerHelper.checkHotbarCurios(player, (p, stack) -> stack.is(PEItems.VOLCANITE_AMULET))) {
			return WalkOnType.ABLE_WITH_SPEED;
		}
		ItemStack chestplate = player.getItemBySlot(EquipmentSlot.CHEST);
		return !chestplate.isEmpty() && chestplate.is(PEItems.GEM_CHESTPLATE) ? WalkOnType.ABLE : WalkOnType.UNABLE;
	}

	private enum WalkOnType {
		ABLE,
		ABLE_WITH_SPEED,
		UNABLE;

		public boolean canWalk() {
			return this != UNABLE;
		}

		public Predicate<Player> applySpeed(boolean onType) {
			//Note: We do this instead of wrapping it to avoid the capturing lambdas
			if (onType && this == ABLE_WITH_SPEED) {
				return Predicates.alwaysTrue();
			}
			return Predicates.alwaysFalse();
		}
	}
}

package moze_intel.projecte.integration;

import moze_intel.projecte.integration.curios.CurioItemCapability;
import moze_intel.projecte.integration.top.TOPIntegration;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.Item;
import net.neoforged.fml.ModList;
import net.neoforged.fml.event.lifecycle.InterModEnqueueEvent;
import net.neoforged.neoforge.capabilities.EntityCapability;
import net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent;
import net.neoforged.neoforge.items.IItemHandler;

public class IntegrationHelper {

	public static final String CURIO_MODID = "curios";
	public static final String EMI_MODID = "emi";
	public static final String TOP_MODID = "theoneprobe";

