package moze_intel.projecte.integration.curios;

import com.google.common.collect.LinkedHashMultimap;
import com.google.common.collect.Multimap;
import net.minecraft.core.Holder;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent;
import top.theillusivec4.curios.api.CuriosCapability;
import top.theillusivec4.curios.api.SlotContext;
import top.theillusivec4.curios.api.type.capability.ICurio;

public record CurioItemCapability(ItemStack stack) implements ICurio {

	@Override
	public ItemStack getStack() {
		return stack;
	}

	@Override
	public void curioTick(SlotContext context) {
		if (!context.cosmetic()) {
			//Note: We act as if curios are being held by the offhand when it comes to ticking
			getStack().inventoryTick(context.entity().level(), context.entity(), Inventory.SLOT_OFFHAND, false);
		}
	}

	@Override
	public Multimap<Holder<Attribute>, AttributeModifier> getAttributeModifiers(SlotContext slotContext, ResourceLocation id) {
		if (!slotContext.cosmetic() && stack.getItem() instanceof IExposesCurioAttributes exposesCurioAttributes) {
			Multimap<Holder<Attribute>, AttributeModifier> attributes = LinkedHashMultimap.create();
			exposesCurioAttributes.addAttributes(attributes);
			return attributes;
		}
		return ICurio.super.getAttributeModifiers(slotContext, id);
	}

	public static void register(RegisterCapabilitiesEvent event, Item item) {
		event.registerItem(CuriosCapability.ITEM, (stack, ctx) -> new CurioItemCapability(stack), item);
	}
}

public static boolean checkHotbar(Player player, BiPredicate<Player, ItemStack> checker) {
	for (int i = 0; i < Inventory.getSelectionSize(); i++) {
		ItemStack stack = player.getInventory().getItem(i);
		if (!stack.isEmpty() && checker.test(player, stack)) {
			return true;
		}
	}
	return false;
}

public static boolean checkHotbarCurios(Player player, BiPredicate<Player, ItemStack> checker) {
	if (checkHotbar(player, checker)) {
		return true;
	}
	ItemStack offhand = player.getOffhandItem();
	if (!offhand.isEmpty() && checker.test(player, offhand)) {
		return true;
	}
	IItemHandler curios = player.getCapability(IntegrationHelper.CURIO_ITEM_HANDLER);
	if (curios != null) {
		for (int i = 0, slots = curios.getSlots(); i < slots; i++) {
			ItemStack stack = curios.getStackInSlot(i);
			if (!stack.isEmpty() && checker.test(player, stack)) {
				return true;
			}
		}
	}
	return false;
}

package moze_intel.projecte.events;

import java.util.EnumSet;
import java.util.Set;
import moze_intel.projecte.PECore;
import moze_intel.projecte.api.capabilities.IAlchBagProvider;
import moze_intel.projecte.api.capabilities.PECapabilities;
import moze_intel.projecte.api.capabilities.item.IAlchBagItem;
import moze_intel.projecte.gameObjs.container.AlchBagContainer;
import moze_intel.projecte.gameObjs.items.AlchemicalBag;
import moze_intel.projecte.gameObjs.items.IFireProtector;
import moze_intel.projecte.handlers.InternalAbilities;
import moze_intel.projecte.utils.PlayerHelper;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.DyeColor;
import net.minecraft.world.item.ItemStack;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.capabilities.Capabilities.ItemHandler;
import net.neoforged.neoforge.event.tick.PlayerTickEvent;
import net.neoforged.neoforge.items.IItemHandler;

@EventBusSubscriber(modid = PECore.MODID)
public class TickEvents {

	@SubscribeEvent
	public static void playerTick(PlayerTickEvent.Post event) {
		Player player = event.getEntity();
		IAlchBagProvider provider = player.getCapability(PECapabilities.ALCH_BAG_CAPABILITY);
		if (provider != null) {
			Set<DyeColor> colorsChanged = EnumSet.noneOf(DyeColor.class);
			for (DyeColor color : getBagColorsPresent(player)) {
				IItemHandler inv = provider.getBag(color);
				for (int i = 0, slots = inv.getSlots(); i < slots; i++) {
					ItemStack current = inv.getStackInSlot(i);
					IAlchBagItem alchBagItem = current.getCapability(PECapabilities.ALCH_BAG_ITEM_CAPABILITY);
					if (alchBagItem != null && alchBagItem.updateInAlchBag(inv, player, current)) {
						colorsChanged.add(color);
					}
				}
			}

			if (player instanceof ServerPlayer serverPlayer) {
				//Only sync for when it ticks on the server
				if (serverPlayer.containerMenu instanceof AlchBagContainer container && serverPlayer.getItemInHand(container.hand).getItem() instanceof AlchemicalBag bag) {
					// Do not sync if this color is open, the container system does it for us and we'll stay out of its way.
					colorsChanged.remove(bag.color);
				}
				provider.sync(serverPlayer, colorsChanged);
			}
		}

		InternalAbilities.tick(player);
		if (!player.level().isClientSide()) {
			if (player.isOnFire() && shouldPlayerResistFire(player)) {
				player.clearFire();
			}
		}
	}
